create extension if not exists pgcrypto;
create table profiles(id uuid primary key references auth.users(id) on delete cascade,name text,email text,phone text,business_name text,default_meeting_duration int default 15,timezone text default 'Asia/Kolkata',created_at timestamptz default now(),updated_at timestamptz default now());
create table business_settings(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,business_name text default 'Ankit Design Studio',logo_url text,website text,phone text,address text,city text default 'Darbhanga',timezone text default 'Asia/Kolkata',created_at timestamptz default now(),updated_at timestamptz default now());
create table leads(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,business_name text not null,contact_name text default '',phone text not null,whatsapp text default '',category text default 'Local Business',city text default 'Darbhanga',address text default '',instagram text default '',website text default '',notes text default '',lead_status text default 'New',call_status text default 'No Answer',interest_level int default 0,next_follow_up timestamptz,last_contacted timestamptz,do_not_call boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table lead_notes(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,note text not null,created_at timestamptz default now());
create table calls(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,provider_call_id text,status text default 'Queued',duration_seconds int default 0,recording_url text,ai_summary text,intent text,interest_score int default 0,created_at timestamptz default now());
create table call_transcripts(id uuid primary key default gen_random_uuid(),call_id uuid references calls(id) on delete cascade,speaker text not null,text text not null,created_at timestamptz default now());
create table ai_scripts(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,name text not null,opening_message text not null,business_pitch text default '',qualification_questions jsonb default '[]',meeting_request text default '',closing_message text default '',is_active boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table meetings(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,start_at timestamptz not null,duration_minutes int default 15,meeting_type text default 'Phone',notes text default '',status text default 'scheduled',google_event_id text,created_at timestamptz default now(),updated_at timestamptz default now());
create table follow_ups(id uuid primary key default gen_random_uuid(),lead_id uuid references leads(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,due_at timestamptz not null,note text default '',status text default 'Pending',created_at timestamptz default now(),updated_at timestamptz default now());
create table notifications(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,type text not null,title text not null,body text default '',read_at timestamptz,created_at timestamptz default now());
create table do_not_call_list(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,phone text not null,reason text default '',source text default 'manual',created_at timestamptz default now(),unique(user_id,phone));
create table audit_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,action text not null,entity_type text,entity_id uuid,metadata jsonb default '{}',created_at timestamptz default now());
create index leads_user_idx on leads(user_id);create index leads_phone_idx on leads(phone);create index calls_user_idx on calls(user_id);create index meetings_user_idx on meetings(user_id);create index followups_user_idx on follow_ups(user_id);
do $$declare t text;begin foreach t in array array['profiles','business_settings','leads','lead_notes','calls','call_transcripts','ai_scripts','meetings','follow_ups','notifications','do_not_call_list','audit_logs'] loop execute format('alter table %I enable row level security',t);end loop;end$$;
create policy profiles_own on profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy business_own on business_settings for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy leads_own on leads for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy notes_own on lead_notes for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy calls_own on calls for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy transcripts_own on call_transcripts for all using(call_id in(select id from calls where user_id=auth.uid())) with check(call_id in(select id from calls where user_id=auth.uid()));
create policy scripts_own on ai_scripts for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy meetings_own on meetings for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy followups_own on follow_ups for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy notifications_own on notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy dnc_own on do_not_call_list for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy audit_own on audit_logs for all using(user_id=auth.uid()) with check(user_id=auth.uid());